#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;
using namespace rpg::presentation;
void check(bool ok){if(!ok){throw std::runtime_error("Classic presentation contract failed");}}
EncounterSetup duel(){auto setup=classic_reference_setup();setup.roster={{"A",Team::A,100,11,200},{"B",Team::B,100,9,100}};setup.rules.timing=TimingProfile::FixedRounds;return setup;}
void profile_separation(){VisualSession classic(duel(),CombatProfile::Classic);check(classic.state().combat.profile==CombatProfile::Classic && classic.state().abilities.empty());VisualSession team;const auto before=team.state();auto r=team.submit_action(before.revision,{*before.combat.battle.current_actor,ActionType::Guard,{},{}});check(r.error==VisualError::CoreRejected && r.action.error==ActionError::GuardDisabled && team.state().combat==before.combat && team.state().revision==before.revision);}
void defense_matches_core(){auto setup=duel();LocalSession core(setup.roster,setup.rules,CombatProfile::Classic,{});VisualSession visual(setup,CombatProfile::Classic);Action guard{"A",ActionType::Guard,{},{}};check(core.apply(guard).accepted() && visual.submit_action(0,guard).accepted());check(visual.state().combat==core.battle().snapshot());const auto action=core.battle().choose_automatic_action();check(action && core.apply(*action).accepted() && visual.step_automatic().accepted());check(visual.state().combat==core.battle().snapshot());check(visual.state().combat.battle.fighters[0].health==96);}
void attack_and_tokens(){VisualSession visual(duel(),CombatProfile::Classic);check(visual.submit_action(0,{"A",ActionType::Attack,"B",{}}).accepted());check(visual.submit_action(0,{"A",ActionType::Attack,"B",{}}).error==VisualError::StaleCommand);auto before=visual.state();check(visual.submit_action(before.revision,{"B",ActionType::Attack,"A",{}}).error==VisualError::NotPlayerTurn);check(visual.state().combat==before.combat);visual.reset();check(visual.submit_action(before.revision,{"A",ActionType::Attack,"B",{}}).error==VisualError::StaleCommand);}
void atomic_rejections(){VisualSession visual(duel(),CombatProfile::Classic);const auto before=visual.state();for(const Action& action:std::vector<Action>{{"A",ActionType::Attack,"missing",{}},{"B",ActionType::Guard,{},{}},{"A",ActionType::Skip,{},{}},{"A",ActionType::Guard,"B",{}}}){check(!visual.submit_action(before.revision,action).accepted());check(visual.state().revision==before.revision && visual.state().combat==before.combat);}}
void common_information(){VisualSession visual(duel(),CombatProfile::Classic);auto view=visual.state();check(target_candidates(view,1)==std::vector<std::string>{"B"});check(target_candidates(view,2).empty());view.combat.battle.fighters[1].health=0;check(target_candidates(view,1).empty());auto fighter=view.combat.battle.fighters[0];fighter.guarding=true;check(effect_details(fighter)[0].find("rounded down")!=std::string::npos);check(ability_details(view,2)[1].find("rounded down")!=std::string::npos);check(ability_details(view,3).back().find("No special skills")!=std::string::npos);check(action_error_message(ActionError::NotBlocked).find("unable to act")!=std::string::npos);}
void full_battle(){VisualSession visual(duel(),CombatProfile::Classic);unsigned count=0;while(visual.state().combat.battle.phase==Phase::Running && count++<100){auto view=visual.state();if(view.automatic){check(visual.step_automatic().accepted());}else{check(visual.submit_action(view.revision,{*view.combat.battle.current_actor,ActionType::Attack,"B",{}}).accepted());}}check(visual.state().combat.battle.phase==Phase::Finished && visual.state().combat.battle.winner==Team::A && visual.state().progress.credits==10);}
int main(){try{profile_separation();defense_matches_core();attack_and_tokens();atomic_rejections();common_information();full_battle();std::cout<<"CLASSIC_VIS_TESTS_RESULT passed=6 total=6\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
